import ctypes
import numpy as np

# Load the libraries
ctypes.CDLL('/usr/local/gsl/lib/libgslcblas.so', mode=ctypes.RTLD_GLOBAL)
gsl = ctypes.CDLL('/usr/local/gsl/lib/libgsl.so')

# Define the gsl_function structure
class GSLFunction(ctypes.Structure):
    _fields_ = [('function', ctypes.CFUNCTYPE(ctypes.c_double, ctypes.c_double, ctypes.c_void_p)),
                ('params', ctypes.c_void_p)]

# Define the integration function prototype
try:
    qc25c = gsl.gsl_integration_qk15  # Use a valid GSL integration function
    qc25c.argtypes = [ctypes.POINTER(GSLFunction), ctypes.c_double, ctypes.c_double,
                      ctypes.POINTER(ctypes.c_double), ctypes.POINTER(ctypes.c_double), ctypes.POINTER(ctypes.c_double)]
    qc25c.restype = ctypes.c_int
except AttributeError:
    raise RuntimeError("The function 'gsl_integration_qk15' is not found in the GSL library.")

# Python wrapper function
def integrate_with_singularity(func, a, b, c):
    def wrapper(x, params):
        return func(x)

    gsl_func = GSLFunction(ctypes.CFUNCTYPE(ctypes.c_double, ctypes.c_double, ctypes.c_void_p)(wrapper), None)
    result = ctypes.c_double()
    abserr = ctypes.c_double()
    neval = ctypes.c_double()

    status = qc25c(ctypes.byref(gsl_func), a, b, ctypes.byref(result), ctypes.byref(abserr), ctypes.byref(neval))

    if status != 0:
        raise RuntimeError(f"GSL integration failed with status code {status}")

    return result.value, abserr.value, int(neval.value)

# Test cases
def assert_test():
    # Define a simple function to integrate
    def test_func(x):
        return np.sin(x)

    # Test the integration without singularity
    result, abserr, neval = integrate_with_singularity(test_func, 0, np.pi, 0)
    assert np.isclose(result, 2.0, atol=1e-2), f"Expected ~2.0, got {result}"
    assert abserr < 0.1, f"Expected error < 0.1, got {abserr}"

if __name__ == "__main__":
    assert_test()
